// ClientPacketLength is the length the server expects for a packet we
// send. Reports false for an id the server does not parse at this
// packetver — which, for a packet we are about to send, means we are
// about to be ignored.
func ClientPacketLength(id uint16) (int, bool) {
	size, ok := clientPacketLengths[id]

	return size, ok
}
